import json
import os
import random
import ctypes
import sys

# When frozen (PyInstaller onefile), __file__ points to a temp dir -> use the EXE folder instead
if getattr(sys, "frozen", False):
    APP_DIR = os.path.dirname(sys.executable)
else:
    APP_DIR = os.path.dirname(os.path.abspath(__file__))

CONFIG_FILE = os.path.join(APP_DIR, "config.json")

# Optional build-time default (build_config.py is gitignored, generated by build.ps1)
try:
    from build_config import DEFAULT_RELAY
except ImportError:
    DEFAULT_RELAY = "ws://localhost:8765"

def enable_dpi_awareness():
    """Makes the process DPI-aware so fonts/screens are correctly sized on HiDPI displays."""
    if sys.platform != "win32":
        return
    try:
        ctypes.windll.shcore.SetProcessDpiAwareness(2)  # Per-monitor DPI aware
    except Exception:
        try:
            ctypes.windll.user32.SetProcessDPIAware()
        except Exception:
            pass

def apply_tk_scaling(root):
    """Scales Tk fonts/widgets to the real monitor DPI. Returns scale factor (1.0 = 96 DPI)."""
    try:
        dpi = root.winfo_fpixels("1i")
        root.tk.call("tk", "scaling", dpi / 72.0)
        return max(1.0, dpi / 96.0)
    except Exception:
        return 1.0

def remember_partner(cfg, partner_id, password):
    """Stores partner at top of recent list (max 8)."""
    recent = [p for p in cfg.get("recent_partners", []) if p.get("id") != partner_id]
    recent.insert(0, {"id": partner_id, "password": password})
    cfg["recent_partners"] = recent[:8]
    save_config(cfg)

def is_admin():
    """Checks whether the current process has administrator privileges."""
    if sys.platform != "win32":
        return True
    try:
        return ctypes.windll.shell32.IsUserAnAdmin() != 0
    except Exception:
        return False

def restart_as_admin():
    """Relaunches the current process with elevated administrator rights via UAC."""
    if sys.platform == "win32":
        try:
            if getattr(sys, "frozen", False):
                exe = sys.executable
                params = ""
            else:
                exe = sys.executable
                params = f'"{os.path.abspath(sys.argv[0])}"'
            ctypes.windll.shell32.ShellExecuteW(
                None, "runas", exe, params, None, 1
            )
            sys.exit(0)
        except Exception:
            return False
    return False

def get_clipboard_text():
    """Reads unicode text from Windows clipboard."""
    if sys.platform != "win32":
        return ""
    try:
        user32 = ctypes.windll.user32
        kernel32 = ctypes.windll.kernel32
        user32.OpenClipboard.argtypes = [ctypes.c_void_p]
        user32.GetClipboardData.argtypes = [ctypes.c_uint]
        user32.GetClipboardData.restype = ctypes.c_void_p
        kernel32.GlobalLock.argtypes = [ctypes.c_void_p]
        kernel32.GlobalLock.restype = ctypes.c_void_p
        kernel32.GlobalUnlock.argtypes = [ctypes.c_void_p]

        if not user32.OpenClipboard(None):
            return ""
        CF_UNICODETEXT = 13
        h_read = user32.GetClipboardData(CF_UNICODETEXT)
        text = ""
        if h_read:
            p_read = kernel32.GlobalLock(h_read)
            if p_read:
                text = ctypes.c_wchar_p(p_read).value or ""
                kernel32.GlobalUnlock(h_read)
        user32.CloseClipboard()
        return text
    except Exception:
        return ""

def set_clipboard_text(text):
    """Sets unicode text into Windows clipboard."""
    if sys.platform != "win32" or text is None:
        return False
    try:
        user32 = ctypes.windll.user32
        kernel32 = ctypes.windll.kernel32
        kernel32.GlobalAlloc.argtypes = [ctypes.c_uint, ctypes.c_size_t]
        kernel32.GlobalAlloc.restype = ctypes.c_void_p
        kernel32.GlobalLock.argtypes = [ctypes.c_void_p]
        kernel32.GlobalLock.restype = ctypes.c_void_p
        kernel32.GlobalUnlock.argtypes = [ctypes.c_void_p]
        user32.OpenClipboard.argtypes = [ctypes.c_void_p]
        user32.SetClipboardData.argtypes = [ctypes.c_uint, ctypes.c_void_p]
        user32.SetClipboardData.restype = ctypes.c_void_p

        CF_UNICODETEXT = 13
        GMEM_MOVEABLE = 0x0002
        raw = (text + '\0').encode('utf-16le')
        h_mem = kernel32.GlobalAlloc(GMEM_MOVEABLE, len(raw))
        if not h_mem:
            return False
        p_mem = kernel32.GlobalLock(h_mem)
        if not p_mem:
            return False
        ctypes.memmove(p_mem, raw, len(raw))
        kernel32.GlobalUnlock(h_mem)

        if not user32.OpenClipboard(None):
            return False
        user32.EmptyClipboard()
        user32.SetClipboardData(CF_UNICODETEXT, h_mem)
        user32.CloseClipboard()
        return True
    except Exception:
        return False

def ensure_desktop_access():
    """Ensures thread has access to active Windows desktop station."""
    if sys.platform == "win32":
        try:
            user32 = ctypes.windll.user32
            hdesk = user32.OpenInputDesktop(0, False, 0x01FF) # GENERIC_ALL
            if hdesk:
                user32.SetThreadDesktop(hdesk)
        except Exception:
            pass

def generate_id():
    """Generates a random 6-digit ID like 384 192."""
    return f"{random.randint(100, 999)} {random.randint(100, 999)}"

def generate_password():
    """Generates a random 6-character alphanumeric password."""
    chars = "abcdefghjkmnpqrstuvwxyz23456789"
    return "".join(random.choices(chars, k=6))

def load_config():
    default_config = {
        "relay_server": DEFAULT_RELAY,
        "my_id": generate_id(),
        "my_password": generate_password(),
        "quality": 55,
        "max_fps": 30,
        "scale": 0.75
    }
    if os.path.exists(CONFIG_FILE):
        try:
            with open(CONFIG_FILE, "r", encoding="utf-8") as f:
                saved = json.load(f)
                default_config.update(saved)
            # Stale localhost entry but a real server is baked in -> use it
            if "localhost" in default_config.get("relay_server", "") and "localhost" not in DEFAULT_RELAY:
                default_config["relay_server"] = DEFAULT_RELAY
                save_config(default_config)
        except Exception:
            pass
    else:
        save_config(default_config)
    return default_config

def save_config(cfg):
    try:
        with open(CONFIG_FILE, "w", encoding="utf-8") as f:
            json.dump(cfg, f, indent=2)
    except Exception:
        pass
